- Shared expert: mlp(&w->sh_gate, &w->sh_up, &w->sh_down, x, b.ye, &b); qmat(&w->sh_router, x) into b.gsh;
  float sg = 1 / (1 + expf(-b.gsh[0])); out[j] += sg * b.ye[j].
- No new variables that go unused (the build uses -Werror).

