    int h, kvh;
    for (h = 0; h < Hq; h++) {
        float *query_h = qg + h * 2 * D;
        float *gate_h = query_h + D;
        float *q_h = q + h * D;
        memcpy(q_h, query_h, D * sizeof(float));
        /* gate_h stays in qg, we'll use it later */
    }

    /* Step 3: RMSNorm */
    for (h = 0; h < Hq; h++) {
        float *q_h = q + h * D;
        op_rmsnorm(q_h, q_h, w->q_norm, D, w->eps);
